@startuml

class FurnitureLine {
  + Name : string
}

class Furniture {
  + Reference : string
  + SellingPrice : double
}

class ComponentType {
  + Code : int
  + ManufacturingPrice : double
  + Type : string
}

class Store {
  + Address : string
  + FaxNumber : string
}

class Order {
  + OrderNumber : int
  + Date : date
}

class OrderLine {
  + Quantity : int
}

FurnitureLine "1" -- "*" Furniture : consists of
Furniture "*" -- "*" ComponentType : composed of
Furniture "*" -- "*" OrderLine
OrderLine "*" -- "1" Furniture
Order "1" -- "*" OrderLine
Order "1" -- "1" Store : placed by
Store "1" -- "*" Order : places

@enduml

